import{describe,it,expect}from"vitest";import{PREAMBLE_KEYWORDS,FUNDAMENTAL_RIGHTS,FUNDAMENTAL_DUTIES,DIRECTIVE_PRINCIPLES,CONSTITUTION_SCHEDULES,KEY_AMENDMENTS,searchConstitutionData,getConstitutionStats}from"../../frontend/constitution-explorer/script.js";describe("Preamble & Fundamental Rights Dataset Integrity",()=>{it("contains 9 core Preamble keywords (Sovereign, Socialist, Secular, etc.)",()=>{expect(PREAMBLE_KEYWORDS.length).toBe(9);const t=PREAMBLE_KEYWORDS.map(t=>t.term);expect(t).toContain("SOVEREIGN"),expect(t).toContain("SOCIALIST"),expect(t).toContain("SECULAR"),expect(t).toContain("DEMOCRATIC"),expect(t).toContain("REPUBLIC")}),it("contains 6 core Fundamental Rights categories",()=>{expect(FUNDAMENTAL_RIGHTS.length).toBe(6);const t=FUNDAMENTAL_RIGHTS.map(t=>t.category);expect(t).toContain("Right to Equality"),expect(t).toContain("Right to Freedom"),expect(t).toContain("Right to Constitutional Remedies")})}),describe("Duties, Schedules & Amendments Integrity",()=>{it("contains 11 Fundamental Duties under Article 51A",()=>{expect(FUNDAMENTAL_DUTIES.length).toBe(11),expect(FUNDAMENTAL_DUTIES[10].article).toContain("51A(k)")}),it("contains 12 Schedules detailing constitutional subjects",()=>{expect(CONSTITUTION_SCHEDULES.length).toBe(12),expect(CONSTITUTION_SCHEDULES[7].subject).toContain("22 Officially recognized"),expect(CONSTITUTION_SCHEDULES[9].subject).toContain("Anti-Defection Law")}),it("contains major landmark amendments (1st, 42nd, 44th, 73rd, 86th, 101st, 106th)",()=>{expect(KEY_AMENDMENTS.length).toBeGreaterThanOrEqual(7);const t=KEY_AMENDMENTS.map(t=>t.number);expect(t.some(t=>t.includes("42nd"))).toBe(!0),expect(t.some(t=>t.includes("86th"))).toBe(!0),expect(t.some(t=>t.includes("106th"))).toBe(!0)})}),describe("Live Search & Stats Functions",()=>{it("searches across rights, duties, schedules, and amendments by query",()=>{const t=searchConstitutionData("education");expect(t.rights.length).toBeGreaterThanOrEqual(1),expect(t.duties.length).toBeGreaterThanOrEqual(1);const e=searchConstitutionData("languages");expect(e.schedules.length).toBe(1),expect(e.schedules[0].number).toBe(8)}),it("returns all items when search query is empty",()=>{const t=searchConstitutionData("");expect(t.rights.length).toBe(FUNDAMENTAL_RIGHTS.length),expect(t.duties.length).toBe(FUNDAMENTAL_DUTIES.length),expect(t.schedules.length).toBe(CONSTITUTION_SCHEDULES.length),expect(t.amendments.length).toBe(KEY_AMENDMENTS.length)}),it("computes constitution statistics correctly",()=>{const t=getConstitutionStats();expect(t.enforcedDate).toBe("26 January 1950"),expect(t.schedulesCount).toBe(12),expect(t.fundamentalDutiesCount).toBe(11),expect(t.recognizedLanguages).toBe(22)})});